package com.chainauth.wallet;
import org.springframework.data.annotation.Id;import org.springframework.data.mongodb.core.index.Indexed;import org.springframework.data.mongodb.core.mapping.Document;import java.time.Instant;
@Document("wallet_nonces") public class WalletNonce{@Id private String id;@Indexed(unique=true)private String nonce;private String address;private long chainId;private String purpose;private String userId;private String message;private Instant issuedAt;@Indexed(expireAfter="0s")private Instant expiresAt;private boolean consumed;
public String getId(){return id;}public void setId(String v){id=v;}public String getNonce(){return nonce;}public void setNonce(String v){nonce=v;}public String getAddress(){return address;}public void setAddress(String v){address=v;}public long getChainId(){return chainId;}public void setChainId(long v){chainId=v;}public String getPurpose(){return purpose;}public void setPurpose(String v){purpose=v;}public String getUserId(){return userId;}public void setUserId(String v){userId=v;}public String getMessage(){return message;}public void setMessage(String v){message=v;}public Instant getIssuedAt(){return issuedAt;}public void setIssuedAt(Instant v){issuedAt=v;}public Instant getExpiresAt(){return expiresAt;}public void setExpiresAt(Instant v){expiresAt=v;}public boolean isConsumed(){return consumed;}public void setConsumed(boolean v){consumed=v;}}
